package com.henson.jarvis.phone;
import android.content.*;import android.security.keystore.*;import org.json.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import java.security.*;import java.nio.charset.StandardCharsets;import java.util.Base64;
public final class TokenVault {
 private final android.content.SharedPreferences prefs;
 public TokenVault(Context context){prefs=context.getSharedPreferences("jarvis-private",Context.MODE_PRIVATE);}
 public String host(){String host=prefs.getString("host",null);if(host==null){host="urn:uuid:"+java.util.UUID.randomUUID();prefs.edit().putString("host",host).commit();}return host;}
 private SecretKey key()throws Exception{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(store.containsAlias("jarvis-chatgpt"))return (SecretKey)store.getKey("jarvis-chatgpt",null);KeyGenerator generator=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");generator.init(new KeyGenParameterSpec.Builder("jarvis-chatgpt",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());return generator.generateKey();}
 public synchronized JSONObject read()throws Exception{String saved=prefs.getString("accounts",null);if(saved==null)return new JSONObject().put("accounts",new JSONObject());JSONObject record=new JSONObject(saved);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.getDecoder().decode(record.getString("iv"))));return new JSONObject(new String(cipher.doFinal(Base64.getDecoder().decode(record.getString("ciphertext"))),StandardCharsets.UTF_8));}
 public synchronized void write(JSONObject value)throws Exception{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());String saved=new JSONObject().put("iv",Base64.getEncoder().encodeToString(cipher.getIV())).put("ciphertext",Base64.getEncoder().encodeToString(cipher.doFinal(value.toString().getBytes(StandardCharsets.UTF_8)))).toString();if(!prefs.edit().putString("accounts",saved).commit())throw new Exception("Could not save the secure ChatGPT session.");}
}
